@dataclass
class Order:
    id: str
    total_cents: int

    @property
    def total_euros(self) -> float:
        return self.total_cents / 100

    def with_discount(self, percent: float) -> "Order":
        return Order(id=self.id, total_cents=int(self.total_cents * (1 - percent / 100)))

